import json,sys,pathlib,hashlib,numpy as np
from PIL import Image
from capture_modes import capture_mode
p=pathlib.Path(sys.argv[1]);r=json.load(open(p));assert capture_mode(r['job'])=='guided';raw=pathlib.Path(r['job']['output']);g=raw.parent/(raw.stem+'_guides');clean=raw.parent/('CLEAN_OIDN_'+raw.stem.removeprefix('INTERNAL_')+'.png');assert clean.is_file();raw_image=Image.open(raw);alpha=np.asarray(raw_image.getchannel('A')) if 'A' in raw_image.getbands() else None;assert alpha is None or np.all(alpha==255),'Nonopaque alpha requires alpha-preserving bridge';a=np.asarray(raw_image.convert('RGB')).astype(float);b=np.asarray(Image.open(g/'raw_passthrough.png').convert('RGB')).astype(float);assert a.shape==b.shape;err=np.abs(a-b);assert err.max()<=1,'Color bridge mismatch'
native=json.loads((g/'png_roundtrip_check.json').read_text()) if (g/'png_roundtrip_check.json').is_file() else None
if native:assert native['opaque'] and native['max_error_native']<=1,'Native-precision PNG bridge mismatch'
contract=json.loads((g/'guide_contract.json').read_text());assert contract['valid'],'OIDN guide contract must pass';r['oidn_guide_contract']=contract
r.update({'capture_mode':'guided','postprocess':'Intel Open Image Denoise2.5.1 CPU RT high quality, guided HDR/albedo/normal; no generic blur','raw_path':str(raw),'clean_path':str(clean),'color_bridge_max_error_8bit':float(err.max()),'color_bridge_mean_error_8bit':float(err.mean()),'color_bridge_native_precision':native,'raw_guides_retained':True,'requires_visual_detail_QA':True,'files_sha256':{str(f):hashlib.sha256(f.read_bytes()).hexdigest() for f in [raw,clean,*map(pathlib.Path,r['guide_paths']),g/'denoised_linear.exr']}});clean.with_suffix('.png.json').write_text(json.dumps(r,indent=2));print('CLEAN_CANDIDATE',str(clean))
